SELECT * FROM audit_log 
WHERE event_type = 'LOGIN_FAILED' AND created_time >= #{startTime}
ORDER BY created_time DESC

SELECT * FROM audit_log 
WHERE created_time BETWEEN #{startTime} AND #{endTime}
ORDER BY created_time DESC

SELECT COUNT(*) FROM audit_log 
WHERE user_id = #{userId} AND status = 'SUCCESS' AND ip_address != #{currentIpAddress} 
AND created_time >= #{recentTime}
